WITH high_earners AS (
    SELECT emp_no, salary FROM salaries WHERE to_date = '9999-01-01' AND salary > 90000
),
current_dept AS (
    SELECT emp_no, dept_no FROM dept_emp WHERE to_date = '9999-01-01'
)
SELECT h.emp_no, h.salary, d.dept_no FROM high_earners h JOIN current_dept d ON h.emp_no = d.emp_no;
